{
  "schemaVersion": "0.2",
  "slug": "masonry",
  "name": "Masonry",
  "family": "A",
  "status": "experimental",
  "purpose": "Arranges uneven-height children into responsive CSS columns without a fixed row grid.",
  "scenarios": [
    "Display a gallery of mixed-height cards",
    "Present a Pinterest-style content feed",
    "Pack dashboard widgets of varying height"
  ],
  "props": {
    "children": {
      "type": "node",
      "required": true,
      "description": "Items packed into columns."
    },
    "columns": {
      "type": "number",
      "required": false,
      "description": "Column count used at the large breakpoint (2, 3, or 4).",
      "default": 3
    },
    "gap": {
      "type": "enum",
      "required": false,
      "description": "Column gap token.",
      "values": [
        "sm",
        "md",
        "lg"
      ],
      "default": "md"
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "gap",
      "values": [
        "sm",
        "md",
        "lg"
      ],
      "default": "md",
      "description": "Column gap token."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Columns follow the container query morph."
    }
  ],
  "composition": {
    "allowedParents": [
      "container",
      "app-shell",
      "page"
    ],
    "allowedChildren": [
      "card",
      "image",
      "article-card"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use Masonry for tabular data; use Table or DataGrid.",
    "Do not force equal-height rows; that is Grid."
  ],
  "a11y": {
    "role": "generic",
    "keyboard": [],
    "focus": "Children remain focusable in source order, which may not match visual column order.",
    "labeling": "Children provide their own labels.",
    "wcag": [
      "1.3.1",
      "1.3.2"
    ]
  },
  "responsive": {
    "strategy": "Root is a query container. Compact is one column; tablet is two; desktop uses the columns prop (3 or 4). No viewport size media.",
    "breakpoints": {
      "compact": "One column.",
      "medium": "Two columns at 48rem container width.",
      "large": "Three or four columns at 80rem container width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. CSS columns follow document direction.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "masonry",
    "states": [
      "default"
    ],
    "intents": [
      "layout-columns"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export type MasonryGap = 'sm' | 'md' | 'lg'

export interface MasonryProps {
  children: ReactNode
  columns?: 2 | 3 | 4
  gap?: MasonryGap
  className?: string
}

export function Masonry({ children, columns = 3, gap = 'md', className }: MasonryProps) {
  const classes = [
    'cu-masonry',
    'cu-masonry--columns-' + columns,
    'cu-masonry--gap-' + gap,
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return (
    <div
      className={classes}
      data-ai-role="masonry"
      data-ai-intent="layout-columns"
      data-ai-state="default"
      data-columns={columns}
    >
      <div className="cu-masonry__track">{children}</div>
    </div>
  )
}

/*
 * Query container: the root is the container; the track consumes it so
 * column-count follows the masonry's own inline size (sidebar embed, split
 * view) rather than the viewport. Compact is one column; @container only
 * enhances. 48rem == breakpoint.tablet, 80rem == breakpoint.desktop
 * (packages/tokens/src/core/breakpoint.json).
 */
.cu-masonry {
  display: block;
  color: var(--cu-color-fg-default);
  container-type: inline-size;
}

.cu-masonry__track {
  column-count: 1;
  column-gap: var(--cu-space-2);
}

.cu-masonry--gap-sm .cu-masonry__track {
  column-gap: var(--cu-space-1);
}

.cu-masonry--gap-md .cu-masonry__track {
  column-gap: var(--cu-space-2);
}

.cu-masonry--gap-lg .cu-masonry__track {
  column-gap: var(--cu-space-3);
}

.cu-masonry__track > * {
  break-inside: avoid;
  margin-block-end: var(--cu-space-2);
}

@container (min-width: 48rem) {
  .cu-masonry__track {
    column-count: 2;
  }
}

@container (min-width: 80rem) {
  .cu-masonry--columns-3 .cu-masonry__track {
    column-count: 3;
  }

  .cu-masonry--columns-4 .cu-masonry__track {
    column-count: 4;
  }
}
